INSERT INTO `memos` VALUES (1,'Business Promotion- SIPLA','<p>&nbsp;</p><p>&nbsp;</p><p>This is with the reference to the above-mentioned subject; we have received the email correspondence from Sales and IT department regarding cost occurred after Business Promotion activity. The details of cost incurred is summarized below:</p><p>&nbsp;</p><figure class=\"table\"><table><tbody><tr><td><strong>SN</strong></td><td><strong>Expenses</strong></td><td><strong>Department</strong></td><td><strong>Cost</strong></td><td><strong>Staff&nbsp;</strong></td><td><strong>Remarks</strong></td></tr><tr><td>1</td><td>Business Promotion</td><td>Sales</td><td>&nbsp; &nbsp; &nbsp;8,500&nbsp;</td><td>Mukunda Raj Pokhrel</td><td>Business Promotion deducting TDS</td></tr><tr><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr><tr><td>&nbsp;</td><td colspan=\"2\">&nbsp;</td><td>&nbsp;</td><td colspan=\"2\">&nbsp;</td></tr></tbody></table></figure><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p>',9,4,'Confirmed',8,4,NULL,'2026-04-29 11:43:27');
/*!40000 ALTER TABLE `memos` ENABLE KEYS */;
UNLOCK TABLES;

